module Box(Seed: number) {
export point Mark = coordinate(x: @Seed, y: 0)
}
const Items: number[] = []
for Tick in @Items {
instance Live = Box(Seed: 1)
point Observed = from(source: @Live::Mark)
}

nui 1
module Box(Seed: number) {
const Chosen: point = if (@Seed > 0) { coordinate(x: @Seed, y: 0) } else { coordinate(x: 1, y: 2) }
export point Mark = from(source: @Chosen)
}
const Items: number[] = []
for Tick in @Items {
instance Live = Box(Seed: 1)
point Observed = from(source: @Live::Mark)
}
